const base=$('Preparar contexto').first().json;
let x={};try{x=JSON.parse(String($json.text||'').replace(/^```(?:json)?\s*/i,'').replace(/```\s*$/,'').trim());}catch{}
const allowed=['producto','tratamiento','turno','otro'];
const tipo=allowed.includes(x.tipo_consulta)?x.tipo_consulta:'otro';
return [{json:{...base,tipo_consulta:tipo,respuesta_cliente:typeof x.respuesta_cliente==='string'&&x.respuesta_cliente.trim()?x.respuesta_cliente.trim().slice(0,4000):'Gracias por tu consulta. Una persona del equipo revisará tu solicitud.',resumen_equipo:typeof x.resumen_equipo==='string'?x.resumen_equipo.slice(0,1000):'Revisar consulta manualmente.'}}];

const b=$('Preparar datos').first().json;
const ok=typeof $json.respuesta_cliente==='string'&&$json.respuesta_cliente.trim().length>0;
return [{json:{...b,status:ok?($json.status||'success'):'error',worker:$json.worker||b.tipo_consulta,respuesta_cliente:ok?$json.respuesta_cliente.slice(0,8000):'Gracias por tu consulta. Una persona del equipo revisará tu solicitud.',estado_caso:'PENDIENTE_REVISION'}}];

