const src=$('Unificar canal').first().json;
const sid=src.canal==='telegram' ? 'tg:'+src.chat_id : 'email:'+src.From;
const rows=$input.all().map(i=>i.json).filter(r=>String(r.Session_ID||'')===sid);
if(rows.length>1) throw new Error('Session_ID duplicado en Base: corregir antes de continuar');
const m=rows[0]||{};
return [{json:{...src,session_id:sid,user_name:src.canal==='telegram'?(src.user_name||src.From):src.From,mensaje_original:src.BodyText,resumen_consolidado:m['Resumen Consolidado']||'Sin memoria previa',estado_caso:m['Estado del Caso']||'NUEVO',datos_clave:m['Datos Clave']||'Sin datos previos'}}];

const b=$('Consolidar respuesta').first().json;
let x;try{x=JSON.parse(String($json.text||'').replace(/^```(?:json)?\s*/i,'').replace(/```\s*$/,'').trim());}catch{}
const valid=x&&typeof x.asunto_principal==='string'&&Array.isArray(x.puntos_clave)&&x.puntos_clave.every(p=>typeof p==='string')&&typeof x.accion_requerida==='string';
const resumen=valid?[x.asunto_principal,...x.puntos_clave,x.accion_requerida].filter(Boolean).join(' | ').slice(0,4000):b.resumen_consolidado;
return [{json:{Session_ID:b.session_id,'Fecha de Actualización':new Date().toISOString(),'Resumen Consolidado':resumen,'Estado del Caso':'PENDIENTE_REVISION','Datos Clave':valid?JSON.stringify({puntos_clave:x.puntos_clave,accion_requerida:x.accion_requerida}).slice(0,3000):b.datos_clave}}];
